// SPDX-License-Identifier: GPL-3.0-or-later
//! Runtime for the mechanically lifted HUD/UI functions (T1909, generated by `tools/hud_lift.py`).
//!
//! The lifted bodies keep the original register file, flags and x87/SSE state explicit so that the
//! Tier 1 differential against the retail bytes (Unicorn) can be exact. They are breadth-first
//! translations, not readable ports (docs/decisions/rust-target-readable.md, "Breadth-first rule").

use crate::memory::GuestMemory;

/// Condition flags a lifted instruction defines.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Flags {
    pub cf: bool,
    pub of: bool,
    pub sf: bool,
    pub zf: bool,
    pub pf: bool,
}

/// Register file, SSE registers (as four dwords each) and the x87 stack at one call.
#[derive(Clone, Debug)]
pub struct Regs {
    pub eax: u32,
    pub ecx: u32,
    pub edx: u32,
    pub ebx: u32,
    pub esi: u32,
    pub edi: u32,
    pub ebp: u32,
    pub esp: u32,
    pub xmm: [[u32; 4]; 8],
    st: [f64; 8],
    top: usize,
    /// Number of values currently on the x87 stack (signed: a callee may pop what its caller pushed).
    pub fdepth: i32,
    /// Base of the `fs` segment (T2008): lifted `fs:[disp]` accesses read `fs_base + disp`. Zero in the retail-bytes oracle.
    pub fs_base: u32,
}

impl Regs {
    pub fn new(esp: u32) -> Regs {
        Regs {
            eax: 0,
            ecx: 0,
            edx: 0,
            ebx: 0,
            esi: 0,
            edi: 0,
            ebp: 0,
            esp,
            xmm: [[0; 4]; 8],
            st: [0.0; 8],
            top: 0,
            fdepth: 0,
            fs_base: 0,
        }
    }
    pub fn fpush(&mut self, value: f64) {
        self.top = (self.top + 7) & 7;
        self.st[self.top] = value;
        self.fdepth += 1;
    }
    pub fn fpop(&mut self) -> f64 {
        let value = self.st[self.top];
        self.top = (self.top + 1) & 7;
        self.fdepth -= 1;
        value
    }
    pub fn st(&self, index: usize) -> f64 {
        self.st[(self.top + index) & 7]
    }
    pub fn set_st(&mut self, index: usize, value: f64) {
        self.st[(self.top + index) & 7] = value;
    }
    pub fn fxch(&mut self, index: usize) {
        let a = self.st(0);
        let b = self.st(index);
        self.set_st(0, b);
        self.set_st(index, a);
    }
}

/// A nested guest call. The caller has already pushed the return address; the implementation reads
/// its arguments from the guest stack (`regs.esp + 4 + 4 * i`) and the registers, and sets `eax`.
pub trait Callee<M: GuestMemory> {
    fn call(&mut self, m: &mut M, regs: &mut Regs, target: u32);
}

pub fn write16<M: GuestMemory>(m: &mut M, address: u32, value: u32) {
    m.write8(address, value as u8);
    m.write8(address.wrapping_add(1), (value >> 8) as u8);
}

pub fn read64<M: GuestMemory>(m: &M, address: u32) -> u64 {
    u64::from(m.read32(address)) | (u64::from(m.read32(address.wrapping_add(4))) << 32)
}

pub fn write64<M: GuestMemory>(m: &mut M, address: u32, value: u64) {
    m.write32(address, value as u32);
    m.write32(address.wrapping_add(4), (value >> 32) as u32);
}

pub fn read_f32<M: GuestMemory>(m: &M, address: u32) -> f32 {
    f32::from_bits(m.read32(address))
}

pub fn mask(bits: u32) -> u32 {
    if bits >= 32 {
        u32::MAX
    } else {
        (1u32 << bits) - 1
    }
}

fn parity(value: u32) -> bool {
    (value as u8).count_ones() % 2 == 0
}

fn result_flags(res: u32, bits: u32) -> Flags {
    Flags {
        cf: false,
        of: false,
        sf: (res >> (bits - 1)) & 1 != 0,
        zf: res & mask(bits) == 0,
        pf: parity(res),
    }
}

pub fn add(a: u32, b: u32, carry: u32, bits: u32) -> (u32, Flags) {
    let wide = u64::from(a) + u64::from(b) + u64::from(carry);
    let res = (wide as u32) & mask(bits);
    let mut f = result_flags(res, bits);
    f.cf = wide >> bits != 0;
    let sign = 1u32 << (bits - 1);
    f.of = ((a ^ res) & (b ^ res) & sign) != 0;
    (res, f)
}

pub fn sub(a: u32, b: u32, borrow: u32, bits: u32) -> (u32, Flags) {
    let wide = u64::from(a).wrapping_sub(u64::from(b)).wrapping_sub(u64::from(borrow));
    let res = (wide as u32) & mask(bits);
    let mut f = result_flags(res, bits);
    f.cf = u64::from(a) < u64::from(b) + u64::from(borrow);
    let sign = 1u32 << (bits - 1);
    f.of = ((a ^ b) & (a ^ res) & sign) != 0;
    (res, f)
}

pub fn logic(res: u32, bits: u32) -> (u32, Flags) {
    let res = res & mask(bits);
    (res, result_flags(res, bits))
}

pub fn shl(a: u32, count: u32, bits: u32, old: Flags) -> (u32, Flags) {
    let count = count & 31;
    if count == 0 {
        return (a, old);
    }
    let wide = u64::from(a) << count;
    let res = (wide as u32) & mask(bits);
    let mut f = result_flags(res, bits);
    f.cf = (wide >> bits) & 1 != 0;
    f.of = ((res >> (bits - 1)) & 1 != 0) != f.cf;
    (res, f)
}

pub fn shr(a: u32, count: u32, bits: u32, old: Flags) -> (u32, Flags) {
    let count = count & 31;
    if count == 0 {
        return (a, old);
    }
    let res = a >> count;
    let mut f = result_flags(res, bits);
    f.cf = (a >> (count - 1)) & 1 != 0;
    f.of = (a >> (bits - 1)) & 1 != 0;
    (res, f)
}

pub fn sar(a: u32, count: u32, bits: u32, old: Flags) -> (u32, Flags) {
    let count = count & 31;
    if count == 0 {
        return (a, old);
    }
    let signed = ((a << (32 - bits)) as i32) >> (32 - bits);
    let res = ((signed >> count) as u32) & mask(bits);
    let mut f = result_flags(res, bits);
    f.cf = ((signed >> (count - 1)) & 1) != 0;
    f.of = false;
    (res, f)
}

/// Rotate left through carry (T2008). Flags as QEMU computes them: OF = msb(old) ^ msb(new), count 0 changes nothing.
pub fn rcl(a: u32, count: u32, bits: u32, old: Flags) -> (u32, Flags) {
    let count = (count & 31) % (bits + 1);
    if count == 0 {
        return (a, old);
    }
    let mut value = a & mask(bits);
    let mut carry = old.cf;
    for _ in 0..count {
        let out = (value >> (bits - 1)) & 1 != 0;
        value = ((value << 1) | u32::from(carry)) & mask(bits);
        carry = out;
    }
    let mut f = old;
    f.cf = carry;
    f.of = (((a >> (bits - 1)) ^ (value >> (bits - 1))) & 1) != 0;
    (value, f)
}

/// Rotate right through carry (T2008), same flag convention as `rcl`.
pub fn rcr(a: u32, count: u32, bits: u32, old: Flags) -> (u32, Flags) {
    let count = (count & 31) % (bits + 1);
    if count == 0 {
        return (a, old);
    }
    let mut value = a & mask(bits);
    let mut carry = old.cf;
    for _ in 0..count {
        let out = value & 1 != 0;
        value = (value >> 1) | (u32::from(carry) << (bits - 1));
        carry = out;
    }
    let mut f = old;
    f.cf = carry;
    f.of = (((a >> (bits - 1)) ^ (value >> (bits - 1))) & 1) != 0;
    (value, f)
}

/// `bsf` (T2008): index of the lowest set bit; a zero source sets ZF and leaves the destination.
pub fn bsf(dst: u32, src: u32, old: Flags) -> (u32, Flags) {
    let mut f = old;
    f.zf = src == 0;
    if src == 0 {
        return (dst, f);
    }
    (src.trailing_zeros(), f)
}

/// `bsr` (T2008): index of the highest set bit; a zero source sets ZF and leaves the destination.
pub fn bsr(dst: u32, src: u32, old: Flags) -> (u32, Flags) {
    let mut f = old;
    f.zf = src == 0;
    if src == 0 {
        return (dst, f);
    }
    (31 - src.leading_zeros(), f)
}

/// Two operand `imul`: truncated product and the overflow flags.
pub fn imul(a: u32, b: u32) -> (u32, Flags) {
    let wide = i64::from(a as i32) * i64::from(b as i32);
    let res = wide as u32;
    let mut f = result_flags(res, 32);
    f.cf = wide != i64::from(res as i32);
    f.of = f.cf;
    (res, f)
}

/// One operand `imul`: `edx:eax = eax * value`.
pub fn imul1(r: &mut Regs, value: u32) -> Flags {
    let wide = i64::from(r.eax as i32) * i64::from(value as i32);
    r.eax = wide as u32;
    r.edx = (wide >> 32) as u32;
    let mut f = result_flags(r.eax, 32);
    f.cf = wide != i64::from(r.eax as i32);
    f.of = f.cf;
    f
}

pub fn mul1(r: &mut Regs, value: u32) -> Flags {
    let wide = u64::from(r.eax) * u64::from(value);
    r.eax = wide as u32;
    r.edx = (wide >> 32) as u32;
    let mut f = result_flags(r.eax, 32);
    f.cf = r.edx != 0;
    f.of = f.cf;
    f
}

/// `idiv r/m32`: `edx:eax / value`. A zero divisor or quotient overflow is a CPU fault.
pub fn idiv(r: &mut Regs, value: u32) {
    let dividend = ((u64::from(r.edx) << 32) | u64::from(r.eax)) as i64;
    let divisor = i64::from(value as i32);
    assert!(divisor != 0, "idiv by zero");
    let quotient = dividend / divisor;
    assert!(quotient == i64::from(quotient as i32), "idiv overflow");
    r.eax = quotient as u32;
    r.edx = (dividend % divisor) as u32;
}

pub fn div(r: &mut Regs, value: u32) {
    let dividend = (u64::from(r.edx) << 32) | u64::from(r.eax);
    let divisor = u64::from(value);
    assert!(divisor != 0, "div by zero");
    let quotient = dividend / divisor;
    assert!(quotient <= u64::from(u32::MAX), "div overflow");
    r.eax = quotient as u32;
    r.edx = (dividend % divisor) as u32;
}

/// Flags after `lahf` (AH): SF, ZF, AF (0), PF, bit 1 set, CF.
pub fn lahf(f: Flags) -> u32 {
    (u32::from(f.sf) << 7) | (u32::from(f.zf) << 6) | (u32::from(f.pf) << 2) | 2 | u32::from(f.cf)
}

/// `comiss`/`ucomiss`/`fcomi`: ZF, PF, CF from the comparison, OF and SF cleared.
pub fn compare_flags(a: f64, b: f64) -> Flags {
    let (zf, pf, cf) = if a.is_nan() || b.is_nan() {
        (true, true, true)
    } else if a > b {
        (false, false, false)
    } else if a < b {
        (false, false, true)
    } else {
        (true, false, false)
    };
    Flags { cf, of: false, sf: false, zf, pf }
}

/// `cvttss2si`: truncate; NaN and out of range give the integer indefinite value.
pub fn cvtt(value: f32) -> u32 {
    if value.is_nan() || value >= 2_147_483_648.0 || value < -2_147_483_648.0 {
        0x8000_0000
    } else {
        value as i32 as u32
    }
}

/// `fist`/`fistp` with the default round-to-nearest-even control word.
pub fn fist(value: f64, bits: u32) -> u64 {
    let rounded = value.round_ties_even();
    match bits {
        16 => {
            if rounded.is_nan() || !(-32768.0..32768.0).contains(&rounded) {
                0x8000
            } else {
                u64::from(rounded as i16 as u16)
            }
        }
        32 => {
            if rounded.is_nan() || !(-2_147_483_648.0..2_147_483_648.0).contains(&rounded) {
                0x8000_0000
            } else {
                u64::from(rounded as i32 as u32)
            }
        }
        _ => {
            if rounded.is_nan() || !(-9.223_372_036_854_775_8e18..9.223_372_036_854_775_8e18).contains(&rounded) {
                0x8000_0000_0000_0000
            } else {
                rounded as i64 as u64
            }
        }
    }
}

/// The game's `_ftol` (0x3C848C): truncate st(0) to a 64 bit integer in `edx:eax`.
///
/// Ported from the original instruction by instruction (T1909): `fistp` rounds to nearest, then a
/// correction step using the rounding error subtracts or adds one, and the scratch register `ecx`
/// is left holding the error word. The Tier 1 oracle compares `ecx` at later calls, so the
/// original's `ecx` side effect is kept.
pub fn ftol(r: &mut Regs) {
    let value = r.fpop();
    let rounded: i64 = if value.is_nan() || value.abs() >= 9.223_372_036_854_775_8e18 {
        i64::MIN
    } else {
        value.round_ties_even() as i64
    };
    let low = rounded as u32;
    let high = (rounded >> 32) as u32;
    let mut sign_word = (value as f32).to_bits();
    if low == 0 {
        sign_word = high;
        if high & 0x7fff_ffff == 0 {
            r.eax = low;
            r.edx = high;
            return;
        }
    }
    let error = (value - rounded as f64) as f32;
    if (sign_word as i32) >= 0 {
        let (word, carry) = error.to_bits().overflowing_add(0x7fff_ffff);
        r.ecx = word;
        let (low_out, borrow) = low.overflowing_sub(u32::from(carry));
        r.eax = low_out;
        r.edx = high.wrapping_sub(u32::from(borrow));
    } else {
        let (word, carry) = (error.to_bits() ^ 0x8000_0000).overflowing_add(0x7fff_ffff);
        r.ecx = word;
        let (low_out, carry_out) = low.overflowing_add(u32::from(carry));
        r.eax = low_out;
        r.edx = high.wrapping_add(u32::from(carry_out));
    }
}

pub fn max_ss(a: f32, b: f32) -> f32 {
    if a > b { a } else { b }
}

pub fn min_ss(a: f32, b: f32) -> f32 {
    if a < b { a } else { b }
}

/// SSE scalar arithmetic with the hardware NaN rule: a NaN first operand wins, else a NaN second
/// operand, quieted. (Rust may commute `a * b`, which would change which payload survives.)
fn nan_rule(a: f32, b: f32) -> Option<f32> {
    if a.is_nan() {
        Some(f32::from_bits(a.to_bits() | 0x0040_0000))
    } else if b.is_nan() {
        Some(f32::from_bits(b.to_bits() | 0x0040_0000))
    } else {
        None
    }
}

pub fn add_ss(a: f32, b: f32) -> f32 {
    nan_rule(a, b).unwrap_or(a + b)
}

pub fn sub_ss(a: f32, b: f32) -> f32 {
    nan_rule(a, b).unwrap_or(a - b)
}

pub fn mul_ss(a: f32, b: f32) -> f32 {
    nan_rule(a, b).unwrap_or(a * b)
}

pub fn div_ss(a: f32, b: f32) -> f32 {
    nan_rule(a, b).unwrap_or(a / b)
}

#[cfg(test)]
mod t2008_forms {
    use super::*;

    #[test]
    fn rotate_through_carry() {
        let carry = Flags { cf: true, ..Flags::default() };
        assert_eq!(rcl(0x8000_0001, 1, 32, carry).0, 0x0000_0003);
        assert!(rcl(0x8000_0001, 1, 32, carry).1.cf);
        assert_eq!(rcr(0x0000_0001, 1, 32, carry).0, 0x8000_0000);
        assert!(rcr(0x0000_0001, 1, 32, carry).1.cf);
        assert_eq!(rcl(0x1234, 0, 32, carry), (0x1234, carry));
        // 8 bit rotates count modulo 9
        assert_eq!(rcl(0x81, 9, 8, carry).0, 0x81);
    }

    #[test]
    fn bit_scan() {
        let (value, flags) = bsf(7, 0x50, Flags::default());
        assert_eq!((value, flags.zf), (4, false));
        assert_eq!(bsr(7, 0x50, Flags::default()).0, 6);
        let (value, flags) = bsf(7, 0, Flags::default());
        assert_eq!((value, flags.zf), (7, true));
    }
}
